/* The Courage to Be Wrong — VoteLens experience.
 * Renders from window.COURAGE (generated by courage_data.py; regenerate, don't
 * hand-edit). No network, no model, no fetch: works from file:// and over HTTP.
 * Presentation only — every value is recomputed in the data layer. */
(function () {
  "use strict";
  var DATA = window.COURAGE || {};

  // ---- tiny helpers -----------------------------------------------------
  function el(tag, attrs, kids) {
    var n = document.createElement(tag);
    if (attrs) for (var k in attrs) {
      if (k === "text") n.textContent = attrs[k];
      else if (k === "html") n.innerHTML = attrs[k];
      else n.setAttribute(k, attrs[k]);
    }
    (kids || []).forEach(function (c) { if (c != null) n.appendChild(c); });
    return n;
  }
  function pct(x) { return x == null ? "—" : (Math.round(x * 1000) / 10) + "%"; }
  function badge(text, cls) { return el("span", { text: text, class: "badge " + (cls || "neutral") }); }
  function labelBadge(lab) {
    var cls = { entailment: "ok", contradiction: "bad", neutral: "neutral" }[lab] || "neutral";
    return badge(lab == null ? "null / none" : lab, cls);
  }
  function sect(label, node, kind) {
    var wrap = el("div", { class: "sect" }, [el("div", { class: "label", text: label })]);
    var body = el("p", { class: "body-copy" + (kind ? " " + kind : ""), text: node });
    wrap.appendChild(body);
    return wrap;
  }

  var L = {
    V: "VERIFIED", H: "HYPOTHESIS", O: "OBSERVED", U: "UNCERTAIN", N: "NOT TESTED"
  };

  // ---- panels -----------------------------------------------------------
  var panels = {};

  panels.overview = function (stage) {
    stage.appendChild(el("h2", { class: "layer-title", text: "0 · How to read this" }));
    stage.appendChild(el("p", { class: "layer-sub",
      text: "Four linked layers share one dataset. The point is not to show a "
          + "system working; it is to make failure mechanisms legible and to keep "
          + "measurement honest while doing it." }));

    var legend = el("div", { class: "card" }, [
      el("h3", { text: "Evidence classes" }),
      el("p", { class: "small muted", text: "Each claim carries one of these. A "
        + "hypothesis is never presented as a finding." }),
      el("div", { class: "legend" }, [
        badge(L.V + " — recomputed from records", "ok"),
        badge(L.O + " — stated in the record, not causal", "neutral"),
        badge(L.H + " — plausible mechanism, untested", "warn"),
        badge(L.U + " — open, needs annotation", "neutral"),
        badge(L.N + " — designed but not run", "bad")
      ])
    ]);
    stage.appendChild(legend);

    stage.appendChild(el("div", { class: "callout info" }, [
      el("p", { class: "small", html:
        "<strong>Three research questions organise the whole experience.</strong> "
        + "RQ1 — can a system tell <em>uncertainty about which referendum</em> apart "
        + "from <em>insufficient evidence for a claim</em>? RQ2 — does independent "
        + "vote grounding reduce invalid outputs without sacrificing evidence "
        + "provenance? RQ3 — how much failure is retrieval scope vs NLI reasoning vs "
        + "output-contract compliance? These are questions for future tests, not "
        + "answers delivered here." })
    ]));

    stage.appendChild(el("div", { class: "card" }, [
      el("h3", { text: "The four layers" }),
      el("ol", { class: "body-copy", html:
        "<li><strong>Failure Gallery</strong> — recorded cases, both arms shown, "
        + "why each is interesting, and what remains unverified.</li>"
        + "<li><strong>Evidence Sufficiency Lab</strong> — the same claim under four "
        + "evidence configurations; the decisive fact is often present throughout, "
        + "only its placement changes.</li>"
        + "<li><strong>Coverage vs Accuracy</strong> — accuracy against a "
        + "coverage-style rate; default is the one comparable pair (paired 54, shared "
        + "denominator), other cohorts shown only as a non-comparable explanatory map; "
        + "rejected answers stay in the denominator.</li>"
        + "<li><strong>Verification Ledger</strong> — the numbers a reviewer might "
        + "assume, checked against the records, including where they are wrong.</li>"
      })
    ]));

    stage.appendChild(el("div", { class: "callout danger" }, [
      el("p", { class: "small", html:
        "<strong>Integrity banner.</strong> Coverage and accuracy use different "
        + "denominators per panel. Single-run development data, no independent "
        + "holdout. <em>Do not reward abstention:</em> a system that refuses to "
        + "answer is not thereby reliable, and rejection must be measured "
        + "independently of correctness. The example cases named in the original "
        + "brief (grouped81-p0-004/028/059) do not exist in any record; the real "
        + "documented cases below are used instead." })
    ]));
  };

  panels.gallery = function (stage, state) {
    var cases = DATA.failure_gallery || [];
    stage.appendChild(el("h2", { class: "layer-title", text: "1 · Failure Gallery" }));
    stage.appendChild(el("p", { class: "layer-sub",
      text: "Four recorded cases. The first three are paired P0 development cases "
          + "(Apertus v1.5 70B): both the baseline (dense-v1) and the candidate "
          + "(vote-aware-v1) outputs are shown, because the difference between them is "
          + "the interesting part. The fourth (row 1344) is an evidence-sensitivity "
          + "case (native 6-bit 8B, A/B/C/D) and appears in the Evidence Sufficiency "
          + "Lab, not as a paired-arm comparison. ← / → move between cards." }));

    // A structured Evidence Passport, one per supported case, generated from the
    // source records by courage_data.py. Empty fields show NOT VERIFIED, never a
    // fabricated value. It sits outside the official submission JSON contract.
    function passportFor(c) {
      var P = DATA.evidence_passport || [];
      for (var k = 0; k < P.length; k++) {
        if (P[k].case_id === c.case_id) return P[k];
        if (c.case_id.indexOf("row-") >= 0
            && P[k].case_id === "sensitivity-row-" + c.case_id.split("row-")[1])
          return P[k];
      }
      return null;
    }
    function ppRow(label, val) {
      return el("tr", {}, [el("td", { class: "small muted", text: label }),
        el("td", { class: "mono small", text: val == null ? "NOT VERIFIED" : String(val) })]);
    }
    function ppPassages(list) {
      if (!Array.isArray(list)) return "NOT VERIFIED";
      return list.map(function (p) { return p.id + (p.page != null ? " (p" + p.page + ")" : ""); }).join(", ");
    }
    function renderPassport(c) {
      var p = passportFor(c);
      if (!p) return null;
      var box = el("div", { class: "sect" });
      box.appendChild(el("div", { class: "label", text: "Evidence Passport (source-record + build-time checks; outside the submission contract)" }));
      var tb = el("table", { class: "ledger" });
      tb.appendChild(ppRow("experiment / model", p.experiment + " · " + (p.model || "NOT VERIFIED")));
      tb.appendChild(ppRow("requested vote", p.requested_vote));
      tb.appendChild(ppRow("claim / booklet language", (p.claim_language || "?") + " / " + (p.booklet_language || "?")));
      tb.appendChild(ppRow("gold label", p.gold_label));
      var per = p.arms || p.conditions || {};
      Object.keys(per).forEach(function (name) {
        var e = per[name];
        tb.appendChild(ppRow(name + " · prediction",
          (e.raw_prediction != null ? e.raw_prediction : e.prediction)
          + " · " + (e.contract_validity || (e.matches_gold != null ? (e.matches_gold ? "matches gold" : "wrong") : ""))));
        tb.appendChild(ppRow(name + " · citation (mechanical)", e.citation_mechanical));
        if (e.validator_error != null) tb.appendChild(ppRow(name + " · validator error", e.validator_error));
        tb.appendChild(ppRow(name + " · passages (ids/pages)", ppPassages(e.passages)));
        var si = e.source_identity;
        if (si) tb.appendChild(ppRow(name + " · source id / hash",
          (si.pdf_sha256 && si.pdf_sha256 !== "NOT VERIFIED" ? si.pdf_sha256.slice(0, 16) + "…" : "NOT VERIFIED")));
      });
      tb.appendChild(ppRow("semantic sufficiency", p.semantic_sufficiency_status));
      tb.appendChild(ppRow("insufficiency scope", p.insufficiency_scope));
      tb.appendChild(ppRow("annotation provenance", p.annotation_provenance));
      if (p.annotation_trust_status) tb.appendChild(ppRow("annotation trust", p.annotation_trust_status));
      tb.appendChild(ppRow("remaining uncertainties", p.remaining_uncertainties));
      box.appendChild(tb);
      return box;
    }

    var list = el("div", { id: "gallery-list" });
    cases.forEach(function (c, i) {
      var card = el("div", { class: "card", "data-idx": i, tabindex: "0",
        role: "group", "aria-label": "Case " + c.case_id });
      card.appendChild(el("h3", { text: c.title }));
      card.appendChild(el("p", { class: "sub", html:
        "<span class='mono'>" + c.case_id + "</span> · " + (c.task_language || "?")
        + " · " + (c.is_paired ? "paired P0 development (CSCS 70B)" : "evidence-sensitivity row (native 6-bit 8B)") }));

      var badges = el("div", { class: "badges" }, [
        badge("gold", "neutral"), labelBadge(c.gold),
        badge("status: " + c.status, c.status === "PARTIALLY VERIFIED" ? "warn" : "neutral")
      ]);
      card.appendChild(badges);

      card.appendChild(sect("The claim", c.claim_en));
      card.appendChild(sect("The vote / what the evidence is about", c.votelabel));
      card.appendChild(sect("Why it is interesting", c.story));

      // arms
      if (c.arms && Object.keys(c.arms).length) {
        var grid = el("div", { class: "armgrid two" });
        ["dense-v1", "vote-aware-v1"].forEach(function (arm) {
          var a = c.arms[arm];
          if (!a) return;
          var head = el("div", { class: "arm-head" }, [
            el("span", { class: "arm-name", text: arm })
          ]);
          var out = el("div", { class: "badges" }, [
            labelBadge(a.raw_label),
            a.valid_output ? badge("accepted output", "ok") : badge("rejected / invalid", "bad"),
            a.citation_verified ? badge("citation verified", "ok") : badge("no verified citation", "warn"),
            a.vote_status ? badge("vote_status: " + a.vote_status, "warn") : null
          ]);
          var rbox = el("div", { class: "arm" }, [head, out]);
          if (a.reasoning) rbox.appendChild(el("p", { class: "reason", text: "Model reasoning (AI-generated, not assumed faithful): " + a.reasoning }));
          grid.appendChild(rbox);
        });
        card.appendChild(el("div", { class: "sect" }, [
          el("div", { class: "label", text: "Recorded outputs (both arms)" }), grid
        ]));
      }

      var pass = renderPassport(c);
      if (pass) card.appendChild(pass);

      card.appendChild(sect("Observed (interpretation)", c.observed, "obs"));
      card.appendChild(sect("Error class (interpretation)", c.error_class));
      card.appendChild(sect("Evidence class & caveat", c.evidence_class, "hyp"));
      card.appendChild(sect("What remains to verify", c.next_step));
      list.appendChild(card);
    });
    stage.appendChild(list);
    state.focus = 0;
    var first = list.querySelector(".card");
    if (first) first.focus();
  };

  panels.lab = function (stage, state) {
    var lab = DATA.evidence_lab || {};
    var rows = Object.keys(lab);
    stage.appendChild(el("h2", { class: "layer-title", text: "2 · Evidence Sufficiency Lab" }));
    stage.appendChild(el("p", { class: "layer-sub",
      text: "One claim, four evidence configurations. 'Sufficient' (B) is "
          + "manually constructed for the case — a case-informed upper bound, "
          + "not a retrievable oracle. C adds reviewed non-decisive distractors; D "
          + "moves the sufficient block behind them, so C and D carry "
          + "identical facts and token counts. Default view shows all four. ← / → "
          + "change the case; press a letter key to toggle a configuration." }));

    var caseSel = state.caseSel == null ? 0 : state.caseSel;
    var sel = rows[caseSel];
    var c = lab[sel];

    // case selector
    var controls = el("div", { class: "controls" });
    rows.forEach(function (r, i) {
      var b = el("button", { text: "row " + r, "data-case": i,
        "aria-pressed": i === caseSel ? "true" : "false" });
      b.addEventListener("click", function () { state.caseSel = i; mount("lab", state); });
      controls.appendChild(b);
    });
    stage.appendChild(controls);

    var card = el("div", { class: "card" });
    card.appendChild(el("h3", { text: c.title }));
    card.appendChild(el("p", { class: "sub", html:
      "gold = <strong>" + c.gold + "</strong> · domain: " + c.domain }));
    card.appendChild(sect("The decisive fact", c.key_fact));
    card.appendChild(sect("What changes across configurations", c.story));

    var condOrder = ["A_original", "B_minimal", "C_minimal_plus_distractors", "D_reordered"];
    var condNames = {
      A_original: ["A · recorded retrieval top-5", "the actual retriever output", "neutral"],
      B_minimal: ["B · sufficient evidence", "curated, NOT a retrievable oracle", "ok"],
      C_minimal_plus_distractors: ["C · B + distractors", "also longer input", "neutral"],
      D_reordered: ["D · distractors first", "same tokens as C, reordered", "warn"]
    };
    condOrder.forEach(function (cond) {
      var d = c.conditions[cond];
      if (!d) return;
      var nm = condNames[cond];
      var arm = el("div", { class: "arm", tabindex: "0" });
      arm.appendChild(el("div", { class: "arm-head" }, [
        el("span", { class: "arm-name", text: nm[0] }),
        el("span", { class: "small muted", text: nm[1] })
      ]));
      arm.appendChild(el("div", { class: "badges" }, [
        labelBadge(d.pred),
        d.correct ? badge("matches gold", "ok") : badge("wrong", "bad")
      ]));
      if (d.reasoning) arm.appendChild(el("p", { class: "reason", text: "Model reasoning: " + d.reasoning }));
      card.appendChild(el("div", { class: "sect" }, [
        el("div", { class: "label", text: "Configuration" }), arm
      ]));
    });

    card.appendChild(el("div", { class: "callout danger" }, [
      el("p", { class: "small", html:
        "<strong>Same facts, different placement → different output.</strong> Rows "
        + "1026 and 1344 keep the decisive fact present from B through D, yet the "
        + "label changes when it is moved behind distractors (single runs). "
        + "Whether that is a positional effect is a <em>hypothesis</em>, not a "
        + "demonstrated cause; and the model's own explanation is not assumed to "
        + "describe its decision. B uses fewer tokens than A, but a curated "
        + "upper bound is not a deployable retriever." })
    ]));

    stage.appendChild(card);
  };

  panels.frontier = function (stage, state) {
    var fr = DATA.coverage_frontier || { points: [] };
    var pts = fr.points || [];
    stage.appendChild(el("h2", { class: "layer-title", text: "3 · The Cost of Coverage" }));
    stage.appendChild(el("p", { class: "layer-sub",
      text: "Accuracy (y) against a coverage-style rate (x). Default view is the one "
          + "genuinely comparable pair: the two paired-70B points share denominator "
          + "n=54 and one metric (official valid-output coverage). The other cohorts "
          + "mix three different x-axes — completion coverage, citation-verification "
          + "rate, valid-output coverage — so the 'all cohorts' view is an explanatory "
          + "map, explicitly NOT one frontier and not a Pareto comparison. "
          + "The central lesson holds either way: higher conditional accuracy among "
          + "accepted answers does not imply higher overall strict correctness." }));

    var toggle = el("div", { class: "controls" });
    var modes = [["paired", "Paired 54-case (one denominator)"], ["all", "All cohorts (not comparable)"]];
    modes.forEach(function (m) {
      var b = el("button", { text: m[1], "data-mode": m[0],
        "aria-pressed": (state.mode || "paired") === m[0] ? "true" : "false" });
      b.addEventListener("click", function () { state.mode = m[0]; mount("frontier", state); });
      toggle.appendChild(b);
    });
    stage.appendChild(toggle);

    var pairedOnly = (state.mode || "paired") === "paired";
    var show = pts.filter(function (p) { return !pairedOnly || p.group === "paired"; });

    // scatter
    var W = 560, H = 320, pad = 46;
    var sx = function (v) { return pad + v * (W - pad * 2); };
    var sy = function (v) { return H - pad - v * (H - pad * 2); };
    var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" role="img" '
      + 'aria-label="Accuracy versus a coverage-style rate; points use different metrics and are not one comparable frontier">';
    svg += '<line class="axis" x1="' + pad + '" y1="' + sy(0) + '" x2="' + (W - pad) + '" y2="' + sy(0) + '"/>';
    svg += '<line class="axis" x1="' + pad + '" y1="' + pad + '" x2="' + pad + '" y2="' + sy(0) + '"/>';
    for (var g = 0; g <= 100; g += 25) {
      svg += '<text x="4" y="' + (sy(g / 100) + 4) + '">' + g + '</text>';
      svg += '<text x="' + sx(g / 100) + '" y="' + (H - pad + 16) + '">' + g + '</text>';
    }
    svg += '<text x="' + (W / 2 - 90) + '" y="' + (H - 6) + '">coverage-style rate (definition differs by point) →</text>';
    svg += '<text x="8" y="14">accuracy →</text>';
    show.forEach(function (p) {
      var color = p.id === "p0-vote-aware" ? "#e0655a"
        : p.id === "p0-dense" ? "#d9a441"
        : p.id.indexOf("grouped") === 0 ? "#6aa9e0" : "#8b95a1";
      var cx = sx(p.coverage).toFixed(1), cy = sy(p.accuracy).toFixed(1);
      svg += '<circle cx="' + cx + '" cy="' + cy + '" r="8" fill="' + color + '" fill-opacity="0.85"/>';
      svg += '<text class="point-label" x="' + (Number(cx) + 11) + '" y="' + (Number(cy) + 4) + '">' + p.label + '</text>';
    });
    svg += '</svg>';

    stage.appendChild(el("div", { class: "card" }, [
      el("h3", { text: pairedOnly ? "Paired 70B comparison (one denominator, one metric)" : "Coverage-style map (mixed denominators and metrics — NOT one frontier)" }),
      el("div", { html: svg }),
      el("div", { class: "legend" }, [
        el("span", { html: '<span class="sw" style="background:#6aa9e0"></span>Grouped (8B, n=81)' }),
        el("span", { html: '<span class="sw" style="background:#8b95a1"></span>Ablation (8B, n=81)' }),
        el("span", { html: '<span class="sw" style="background:#d9a441"></span>P0 dense-v1 (70B, n=54)' }),
        el("span", { html: '<span class="sw" style="background:#e0655a"></span>P0 vote-aware (70B, n=54)' })
      ]),
      el("p", { class: "small muted", text: fr.caveat })
    ]));

    // per-point table
    var tb = el("table", { class: "ledger" });
    tb.appendChild(el("tr", {}, [
      el("th", { text: "Point" }), el("th", { text: "Coverage" }),
      el("th", { text: "Accuracy" }), el("th", { text: "Denominator & basis" })
    ]));
    show.forEach(function (p) {
      tb.appendChild(el("tr", {}, [
        el("td", { html: "<strong>" + p.label + "</strong><br><span class='small muted'>"
          + p.cohort + " · " + p.model + "</span>" }),
        el("td", { class: "mono", text: pct(p.coverage) }),
        el("td", { class: "mono", text: pct(p.accuracy) }),
        el("td", { class: "small", html: "<em>coverage (" + (p.coverage_metric || "n/a")
          + "):</em> " + p.coverage_basis
          + "<br><em>accuracy:</em> " + p.accuracy_basis })
      ]));
    });
    stage.appendChild(el("div", { class: "card" }, [el("h3", { text: "Reading each point honestly" }), tb]));

    // the headline finding + the untested control
    stage.appendChild(el("div", { class: "callout info" }, [
      el("p", { class: "small", html:
        "<strong>Do not reward abstention.</strong> In the paired 70B run, "
        + "vote-aware-v1 had <em>higher</em> raw-label accuracy than dense (41/54 vs "
        + "40/54) but threw away many correct answers: it rejected all 18 gold-neutral "
        + "cases, and 18 of its 29 rejections were gold-correct. Dense also had "
        + "correct-but-unrenderable outputs (8 of 11 invalid were gold-correct). So a "
        + "high error rate is not proof of reliability, and a rejection rate must be "
        + "measured against whether the answer was actually right." })
    ]));

    var ctrl = DATA.coverage_frontier.control;
    stage.appendChild(el("div", { class: "callout danger" }, [
      el("p", { class: "small", html:
        "<strong>" + ctrl.label + ".</strong> " + ctrl.planned + " "
        + "<em>" + ctrl.why_not_run + "</em>" })
    ]));
    if (pairedOnly) {
      stage.appendChild(el("p", { class: "small muted",
        text: "This is the one comparable pair: same cohort, same model, same "
            + "denominator (n=54), same metric (official valid-output coverage). "
            + "Dense-v1 has higher strict accuracy AND higher coverage than "
            + "vote-aware-v1 here — that is a within-domain comparison, not a "
            + "Pareto frontier claim." }));
    } else {
      stage.appendChild(el("p", { class: "small muted",
        text: "Note: in the grouped-81 cohort dense Top-5 had higher accuracy than "
            + "full-booklet but LOWER completion coverage (80/81 vs 81/81 — one reply "
            + "hit the token limit). Its x-axis is completion coverage, unlike the "
            + "paired points' valid-output coverage and the ablation point's "
            + "citation-verification rate, so these points are plotted together only "
            + "to be read as separate studies. Reading them as one tradeoff frontier "
            + "would be the exact error this panel is built to prevent." }));
    }
  };

  panels.ledger = function (stage, state) {
    var led = DATA.verification_ledger || { corrections: [] };
    stage.appendChild(el("h2", { class: "layer-title", text: "4 · Verification Ledger" }));
    stage.appendChild(el("p", { class: "layer-sub",
      text: "Claims a reviewer might be handed, checked against the records. The "
          + "ledger's job is to catch the project being wrong, including where the "
          + "brief's own example IDs and counts did not survive verification." }));

    var tb = el("table", { class: "ledger" });
    tb.appendChild(el("tr", {}, [
      el("th", { text: "Asserted" }), el("th", { text: "Record says" }),
      el("th", { text: "Status" })
    ]));
    led.corrections.forEach(function (c) {
      var cls = c.status.indexOf("INCONSISTENT") >= 0 ? "bad"
        : c.status.indexOf("AMBIGUOUS") >= 0 ? "warn"
        : c.status.indexOf("NOT ESTABLISHED") >= 0 ? "warn" : "ok";
      tb.appendChild(el("tr", {}, [
        el("td", { class: "small", html: "<em>" + c.asserted + "</em>" }),
        el("td", { class: "small", html: c.recorded + "<br><span class='muted'>" + c.note + "</span>" }),
        el("td", { html: '<span class="badge ' + cls + '">' + c.status + "</span>" })
      ]));
    });
    stage.appendChild(el("div", { class: "card" }, [
      el("h3", { text: "Corrected ledger (29 candidate rejections, paired 70B run)" }),
      tb,
      el("p", { class: "small muted", style: "margin-top:.8rem", html:
        "Recomputed from <span class='mono'>predictions.jsonl</span> "
        + "(SHA-256 <span class='mono'>" + (DATA.provenance.paired_predictions_sha256 || "").slice(0, 16)
        + "…</span>). Gate taxonomy: 14 vote_status=unrecognised + 15 null/invalid "
        + "vote_status = 29, all stopped at the identity gate; none produced a "
        + "quotation, so citation verification never ran on them (it ran on the 25 "
        + "accepted outputs, 25/25 passed). This is analysis of recorded outputs, not "
        + "a second model evaluation." })
    ]));

    var f = led.recomputed_facts;
    if (f && typeof f === "object") {
      var vstate = (DATA.verification && DATA.verification.state) || "NOT RE-VERIFIED";
      var factsCard = el("div", { class: "card" }, [
        el("h3", { text: "Facts recomputed at build time (this build: " + vstate + ")" }),
        el("p", { class: "small muted", text:
          "These figures were recomputed from predictions.jsonl when the dataset "
          + "was last BUILT, on a machine that had the Git-ignored raw tree. "
          + "Opening this page in a clean checkout does NOT re-verify them and does "
          + "NOT prove the raw files are present here. To re-verify, restore "
          + "data/experiments/, check the SHA-256, and re-run courage_data.py. "
          + "Until then read this as a historical build-time result, not a live check:" })
      ]);
      var ul = el("ul", { class: "mono small" });
      Object.keys(f).forEach(function (k) {
        ul.appendChild(el("li", { text: k + " = " + JSON.stringify(f[k]) }));
      });
      factsCard.appendChild(ul);
      stage.appendChild(factsCard);
    }
  };

  // ---- mount + keyboard -------------------------------------------------
  var ORDER = ["overview", "gallery", "lab", "frontier", "ledger"];
  var TITLES = {
    overview: "0 · Overview", gallery: "1 · Failure Gallery",
    lab: "2 · Evidence Sufficiency Lab", frontier: "3 · Coverage vs Accuracy",
    ledger: "4 · Verification Ledger"
  };
  var state = { tab: "overview", caseSel: 0, galleryFocus: 0, mode: "paired" };
  var stage = document.getElementById("stage");
  var tabsEl = document.getElementById("tabs");

  function mount(name, st) {
    state.tab = name;
    stage.innerHTML = "";
    stage.setAttribute("aria-label", TITLES[name]);
    panels[name](stage, st || state);
    Array.prototype.forEach.call(tabsEl.children, function (t) {
      t.setAttribute("aria-selected", t.getAttribute("data-tab") === name ? "true" : "false");
    });
  }

  ORDER.forEach(function (name) {
    var t = el("button", { role: "tab", text: TITLES[name], "data-tab": name,
      "aria-selected": name === state.tab ? "true" : "false" });
    t.addEventListener("click", function () { mount(name); });
    tabsEl.appendChild(t);
  });

  document.addEventListener("keydown", function (ev) {
    var tag = (ev.target && ev.target.tagName || "").toLowerCase();
    if (tag === "input" || tag === "textarea" || (ev.target && ev.target.isContentEditable)) return;
    if (ev.metaKey || ev.ctrlKey || ev.altKey) return;
    var n = parseInt(ev.key, 10);
    if (n >= 1 && n <= 5) { ev.preventDefault(); mount(ORDER[n - 1]); return; }
    if (ev.key === "Escape") { document.activeElement && document.activeElement.blur(); return; }
    // within-panel navigation for the gallery
    if (state.tab === "gallery" && (ev.key === "ArrowLeft" || ev.key === "ArrowRight")) {
      var cards = stage.querySelectorAll(".card");
      if (!cards.length) return;
      var i = -1;
      for (var k = 0; k < cards.length; k++) if (cards[k] === document.activeElement) i = k;
      if (i < 0) i = 0;
      else i = ev.key === "ArrowRight" ? Math.min(cards.length - 1, i + 1) : Math.max(0, i - 1);
      cards[i].focus();
      ev.preventDefault();
    }
    // lab: arrow keys move between cases
    if (state.tab === "lab" && (ev.key === "ArrowLeft" || ev.key === "ArrowRight")) {
      var rows = Object.keys(DATA.evidence_lab || {});
      state.caseSel = ((state.caseSel || 0) + (ev.key === "ArrowRight" ? 1 : -1) + rows.length) % rows.length;
      mount("lab");
      ev.preventDefault();
    }
  });

  mount("overview");
})();